import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        long min_residual = x;
        long num = 0;
        long den = 1;

        for (long denom = 1; denom <= n; ++denom) {
            long a_start = Math.max(x * denom / y - 10, 0);
            for (int offset = 0; offset < 20; ++offset) {
                long a_candidate = a_start + offset;
                long diff_value = Math.abs(x * denom - a_candidate * y);
                if (min_residual * denom > diff_value * den) {
                    min_residual = diff_value;
                    num = a_candidate;
                    den = denom;
                } else if (min_residual * denom == diff_value * den) {
                    if (den > denom || (den == denom && num > a_candidate)) {
                        num = a_candidate;
                        den = denom;
                    }
                }
            }
        }
        System.out.println(num + "/" + den);
        scanner.close();
    }
}
